    "name": "যন্ত্রপাতি আর সরঞ্জামের লাইব্রেরি",
    "purpose": "কিনে ফেলার বদলে প্রতিবেশীরা লাইব্রেরি থেকে যন্ত্রপাতি নিয়ে কাজ সারুন — খরচও বাঁচে, অপচয়ও কমে।",
    "whoItServes": "ভাড়াটিয়া, সদ্য বাড়ি-নেওয়া মানুষ, শখের কারিগর, আর মাঝে-মধ্যে মেরামত বা প্রজেক্টে হাত দেওয়া যে কেউ।",
