    "setupHours": 20,
    "defaultCategory": "infrastructure",
    "firstSteps": "একটা ড্রিলও ঘরে তোলার আগে, যিনি জায়গা দিচ্ছেন তাঁর সাথে খোলাখুলি কথা বলুন — যন্ত্রপাতির লাইব্রেরির সাথে ঘর করা মানে আসলে কী: শব্দ, বাড়তে থাকা জিনিসের স্তূপ, খোলা সময়ে দরজায় অচেনা মানুষ। তারপর প্রতিবেশীদের জিজ্ঞেস করুন, তাঁরা সত্যি কী কী নিতে আসবেন; দশটা চাওয়া যন্ত্রের তালিকা, কেউ চায় না এমন জিনিসে ঠাসা গ্যারেজের চেয়ে ঢের ভালো।",
    "commonPitfalls": "যন্ত্রপাতির লাইব্রেরি মরে ফেরতের দিন পেরোনোর পরের নীরবতায়: কেউ খোঁজ নেন না, যন্ত্র আর ফেরেই না, তাকগুলো খালি হয়ে যায়। কড়া নিয়মের চেয়ে বন্ধুর মতো মনে করিয়ে দেওয়ার অভ্যাসটাই বেশি কাজের — আর জিনিস নিতে ‘না’ বলতেও তৈরি থাকুন, নইলে পাড়ার ভাঙা জিনিস ফেলার জায়গা হয়ে উঠবেন।",
