    "whatYoullNeed": "গাড়ি আর গায়ের জোর আছে এমন সাহায্যকারী, মাল সরানোর সরঞ্জাম, আর স্পষ্ট নিরাপত্তার নিয়ম। অনিরাপদ জায়গা ছাড়ছেন এমন কারও বেলায় নতুন ঠিকানা, তারিখ আর খুঁটিনাটি একদম গোপন রাখুন, আর সময় ও নিরাপত্তার প্রশ্নে চলুন সেই মানুষটির কথামতোই।",
    "setupHours": 14,
    "defaultCategory": "transport",
    "suggestsWorkDays": true,
    "firstSteps": "একটা ট্রাক জোগাড়ের আগেই তাঁদের সাথে কথা বলুন, যাঁরা এরকম ডাক আগে থেকেই সামলান — পারিবারিক নির্যাতনের শিকার মানুষের পাশে দাঁড়ানো কর্মী, ভাড়াটেদের সংগঠক, বয়স্কদের নিয়ে কাজ করা সংস্থা — অনুরোধ কীভাবে আপনার কাছে পৌঁছাবে আর কতটা গোপনীয়তা তাঁরা আশা করবেন; কিছু বাসা-বদল মানেই কেউ অনিরাপদ ঘর ছেড়ে বেরোচ্ছেন। তারপর শক্ত কাঁধের তিন-চারজন আর একটা গাড়ি জোগাড় করুন, আর প্রথম ছোট্ট বাসা-বদলটা সবাই মিলে মেপে নিন।",
    "commonPitfalls": "বাসা-বদলের দল চোট পায় বা হাঁপিয়ে ওঠে দ্রুতই: হাতের তুলনায় বড় বেশি কাজ, ভুল ভঙ্গিতে ভার তোলা কেউ, কিংবা সমন্বয়কের ফোন থেকে বেরোনোই উচিত ছিল না এমন ঠিকানা কোনো গ্রুপ চ্যাটে। কাজ রাখুন নিজেদের ঘোষণা করা সীমার ভেতরে, আর নিরাপত্তা-জড়ানো প্রতিটা বাসা-বদলের খুঁটিনাটিকে এমনভাবে দেখুন যেন তা কাউকে বিপদে ফেলতে পারে — কারণ সত্যিই পারে।",
