    "firstSteps": "আপনার প্রথম আলাপটা একটা স্কুলের সাথে — কাউন্সেলর, পরিবারের সাথে যোগাযোগ রাখা শিক্ষক, বা বাবা-মায়েদের সাথে সমন্বয় করেন এমন কেউ — যিনি আসল জিনিসের তালিকা জানেন, আর জানেন কোন পরিবারগুলো চুপচাপ না নিয়েই চালিয়ে নেয়। কী জোগাড় করবেন আর পরিবারগুলো কীভাবে খবর পাবে, তা ঠিক হোক তাঁদের কথায়; বাবা-মায়েরা যাঁদের এমনিই ভরসা করেন, তাঁদের হাত ঘুরে পৌঁছানো আয়োজন এমন বাচ্চাদের কাছে পৌঁছায়, লিফলেট যাদের কোনোদিন ছোঁবে না।",
    "commonPitfalls": "চেনা ব্যর্থতাটা হলো দান করা ফোল্ডারের পাহাড়, অথচ তালিকা যে খাতাগুলো সত্যিই চায় তার একটাও নেই — যা দেওয়া সহজ তাই জোগাড় করা, যা দরকার তা নয়। যেটা কাঁটার মতো বেঁধে, সেটা হলো আয় যাচাইয়ের মতো লাগা বিলি; আয়ের কাগজপত্র বাদ দিন, বাচ্চারা নিজের স্কুলব্যাগ নিজেই বাছুক — তাহলে কেউ আর নিজেকে যাচাইয়ের মুখে পড়া ভেবে ফেরেন না।",
