    "whoItServes": "সাধ্য নেই অথচ আইনি ঝামেলায় পড়েছেন — এমন যে কেউ: বাড়িভাড়া, অভিবাসন, ঋণের মামলা, পারিবারিক বিষয়, বা সরকারি ভাতার ব্যাপার।",
