    "purpose": "সমন্বয়ের মেরুদণ্ড হয়ে উঠুন — একটাই জায়গা, যেখানে আপনার উদ্যোগের সব প্রজেক্ট জুড়ে দরকার আর সাহায্য মেলানো হয়।",
