    "whatYoullNeed": "দরকার জানানোর একটা ব্যবস্থা, সাহায্যকারী আর জিনিসপত্রের তালিকা, কয়েকজন সমন্বয়কারী, আর একটা মূল ঠিকানা-তালিকা। কেন্দ্রের হাতে প্রতিবেশীদের জীবনের স্পর্শকাতর তথ্য থাকে — যতটুকু লাগে ততটুকুই নিন, সাবধানে আগলে রাখুন, আর খুঁটিনাটি জানান কেবল তাঁদেরই, সাহায্য করতে যাঁদের সেটা লাগবে।",
