    "whoItServes": "ফৌজদারি, অভিবাসন, উচ্ছেদ বা পারিবারিক আদালতের তারিখের মুখে দাঁড়ানো প্রতিবেশী আর তাঁদের পরিবার — একা আদালতে যাওয়ার দাম হতে পারে চাকরি, বাচ্চার দেখাশোনা, এমনকি আশাটুকুও।",
