    "setupHours": 16,
    "defaultCategory": "other",
    "firstSteps": "শুরু করুন তাঁদের দিয়েই, তারিখগুলো যাঁদের: পাশে থাকা হয় কেবল আদালতের মুখে দাঁড়ানো মানুষটির ডাকে, আর তাঁর আইনজীবীর সঙ্গে তাল মিলিয়ে। আগে নিজেদের পরিচয় দিন বিনা খরচের ডিফেন্স আইনজীবীদের দপ্তরে, আর আদালত চত্বরে আগে থেকে থাকা আদালত-নজর বা জামিনের-টাকার তহবিল চালানো দলগুলোর কাছে — কোন শুনানিতে সঙ্গ দরকার আর আইনি দিকটা না ছুঁয়ে কীভাবে কাজে আসা যায়, তাঁরাই বলে দেবেন।",
    "commonPitfalls": "এখানে ক্ষতি হয় নিজের থেকে বেশি করতে গেলে: করিডরে দাঁড়িয়ে কোনো সাহায্যকারীর রফা “বুঝিয়ে দেওয়া”, মামলার কথা এমন জায়গায় বলা যেখানে সরকারপক্ষের আইনজীবী শুনে ফেলেন, দর্শকের আসন থেকে এমন প্রতিক্রিয়া যা বিচারকের চোখে লাগে — যার যে-কোনোটা ঠিক সেই মানুষটিরই ক্ষতি করতে পারে, যাঁর জন্য এসেছেন। চুপচাপ ভুলটা ব্যবস্থাপনার: যাচাই-না-করা তারিখ বা ভেস্তে যাওয়া গাড়ি মানে শুনানি ফসকানো, আর হয়তো গ্রেপ্তারি পরোয়ানা।",
