    "defaultCategory": "food",
    "firstSteps": "শুরুটা হোক খাবারের জোগান আর প্রথম পাঁচজন বয়স্ককে দিয়ে, কোনো তালিকা দিয়ে নয়: ‘সবার রান্নাঘর’-এর রান্নার দল বা রাঁধতে রাজি দু-একজনের সাথে কথা বলুন, প্রতি সপ্তাহে তাঁরা নিশ্চিতভাবে কতটা বানাতে পারবেন — আর বয়স্কদের নিয়ে কাজ করা কর্মী, পাড়ার স্বাস্থ্যকর্মী ও ওষুধের দোকানিদের জিজ্ঞেস করুন, সত্যিই কার খাবার জুটছে না। প্রথম সাহায্যকারীদের যাচাই করুন প্রথম খাবার পৌঁছানোর আগে, পরে নয় — যে ভরসা গড়ছেন, তা বাঁচে-মরে এর ওপরই: ওই দরজাগুলো দিয়ে ভেতরে কে ঢুকছেন।",
    "commonPitfalls": "বিপজ্জনক ব্যর্থতা হলো কোনো সংকেত চোখ এড়িয়ে যাওয়া — সাড়া-না-দেওয়া দরজা কোনো সাহায্যকারীর গা-ছাড়া ভাবে পেরিয়ে যাওয়া, কারণ তখন কী করতে হয় তা কেউ লিখে রাখেনি; বা এমন কোনো অ্যালার্জি, যা রুটের কাগজে কখনো ওঠেইনি। ধীর ব্যর্থতা হলো অনিয়ম: বয়স্করা দিনটা সাজান এই সাক্ষাৎ ঘিরে, আর যে রুট সপ্তাহের পর সপ্তাহ বাদ পড়ে, তা তাঁদের শিখিয়ে দেয় — আপনাদের ওপর ভরসা না করাই ভালো। কখনো-সখনো বিশজনের কাছে পৌঁছানোর চেয়ে প্রতি সপ্তাহে পাঁচজনের কাছে পৌঁছানো ঢের ভালো।",
