    "whoItServes": "বন্যা, ঝড়, আগুনসহ নানা দুর্যোগে বিপদে পড়া মানুষজন — শুরুটা তাঁদের দিয়ে, যাঁরা দূরে যেতে বা অপেক্ষা করতে সবচেয়ে কম পারেন।",
    "whatYoullNeed": "আগে থেকে কথা-পাকা একটা জায়গা আর তার বিকল্প, জিনিস জোগাড়ের পথঘাট, হঠাৎ ডাকে আসা সাহায্যকারীদের একটা দল, আর ‘বিপদ-আপদ ও দুর্যোগে তৈরি থাকার নেটওয়ার্ক’-এর সাথে সমন্বয় — এর প্রায় সবটাই দুর্যোগের আগে সেরে রাখা চাই, কারণ পরে বড্ড দেরি।",
