    "commonPitfalls": "এ ধরনের কেন্দ্র ব্যর্থ হয় দুই দিকে: এক, যে কেন্দ্র শুধু খসড়ায় আছে, কেউ কখনো মহড়া দেয়নি — ফলে আসল দিনের প্রথমটা পোড়ে সেই প্রশ্নে, যার উত্তর একটা মহড়াই দিয়ে দিত; দুই, যে কেন্দ্র দরজা খুলে দেয় দানের এমন ঢলে, যা সে বাছতে পারে না — মানুষের যখন পানি দরকার, তখন সে বসে থাকে অকেজো জামাকাপড়ের গুদাম হয়ে। চুপচাপ ক্ষতিটা হলো শর্ত-বাঁধা বিলি: কাউকে যেই প্রমাণ করতে হলো তিনি সাহায্য পাওয়ার যোগ্য, সেই মুহূর্তে আপনি সেই ব্যবস্থাটাই আবার বানিয়ে ফেললেন, যেটা পাশ কাটাতে এটা গড়েছিলেন।",
