    "commonPitfalls": "এই প্রজেক্ট ভাঙতে পারে সশব্দে, নয়তো নিঃশব্দে। সশব্দে: শিশুদের কাছে যাচাই-না-করা কেউ, বা অনুমতি ছাড়া বাইরে যাওয়া কোনো পরিবারের গল্প — দুটোর যেকোনোটা এক শিশুর ক্ষতি করতে, এক শিশুর ঘর ভেঙে দিতে আর এক দিনে প্রজেক্ট শেষ করে দিতে পারে। নিঃশব্দে: অগোছালো দানের পাহাড়, ওদিকে এক লালনপালনকারী তিন সপ্তাহ ধরে একটা শিশুখাটের অপেক্ষায়; বা সংস্থাগুলোকে প্রতিপক্ষ ভাবা, যতদিন না তারা পরিবার পাঠানোই বন্ধ করে। এখানে ছোট, যাচাই-করা, হাতে-হাত-মেলানো দল বড় আর এলোমেলোর চেয়ে ভালো — প্রতিবার।",
